--
-- Table structure for table `asientos`
--

DROP TABLE IF EXISTS `asientos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `asientos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `clave_idempotencia` varchar(80) NOT NULL,
  `tipo` enum('transferencia','deposito','retiro','pago_cuota','consumo_tarjeta','pago_tarjeta','interes','mora','comision','ajuste','nota_abono','nota_cargo','reverso','arreglo_pago','condonacion','compensacion','interbancaria','pago_servicio','remesa','plazo_fijo','cheque','programada') NOT NULL,
  `referencia` varchar(64) NOT NULL,
  `descripcion` varchar(255) NOT NULL DEFAULT '',
  `creado_en` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `creado_por` int(10) unsigned DEFAULT NULL COMMENT 'Nulo cuando el asiento lo origina el sistema y no una persona',
  `ip_origen` varbinary(16) NOT NULL,
  `reversa_a` bigint(20) unsigned DEFAULT NULL,
  `hash_anterior` char(64) NOT NULL,
  `hash_actual` char(64) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uuid` (`uuid`),
  UNIQUE KEY `clave_idempotencia` (`clave_idempotencia`),
  UNIQUE KEY `referencia` (`referencia`),
  KEY `fk_asiento_usuario` (`creado_por`),
  KEY `fk_asiento_reversa` (`reversa_a`),
  KEY `idx_tipo_fecha` (`tipo`,`creado_en`),
  KEY `idx_creado_en` (`creado_en`),
  CONSTRAINT `fk_asiento_reversa` FOREIGN KEY (`reversa_a`) REFERENCES `asientos` (`id`),
  CONSTRAINT `fk_asiento_usuario` FOREIGN KEY (`creado_por`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2700 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `asientos`
--

LOCK TABLES `asientos` WRITE;
/*!40000 ALTER TABLE `asientos` DISABLE KEYS */;
