DROP TABLE IF EXISTS `cobranza_casos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cobranza_casos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `folio` varchar(24) NOT NULL,
  `credito_id` int(10) unsigned NOT NULL,
  `usuario_id` int(10) unsigned NOT NULL,
  `etapa` enum('preventiva','administrativa','extrajudicial','judicial','sentencia','recuperado','castigado') NOT NULL DEFAULT 'administrativa',
  `gestor_id` int(10) unsigned DEFAULT NULL,
  `deuda_cent` bigint(20) unsigned NOT NULL DEFAULT 0,
  `mora_cent` bigint(20) unsigned NOT NULL DEFAULT 0,
  `dias_mora` int(10) unsigned NOT NULL DEFAULT 0,
  `cuotas_vencidas` smallint(5) unsigned NOT NULL DEFAULT 0,
  `juzgado` varchar(160) DEFAULT NULL,
  `referencia_judicial` varchar(80) DEFAULT NULL,
  `abogado` varchar(160) DEFAULT NULL,
  `demanda_en` date DEFAULT NULL,
  `emplazamiento_en` date DEFAULT NULL,
  `sentencia_en` date DEFAULT NULL,
  `sentencia_favorable` tinyint(1) DEFAULT NULL,
  `cerrado_en` datetime DEFAULT NULL,
  `cerrado_por` int(10) unsigned DEFAULT NULL,
  `motivo_cierre` varchar(400) DEFAULT NULL,
  `recuperado_cent` bigint(20) unsigned NOT NULL DEFAULT 0,
  `abierto_en` datetime NOT NULL DEFAULT current_timestamp(),
  `actualizado_en` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cob_uuid` (`uuid`),
  UNIQUE KEY `uq_cob_folio` (`folio`),
  UNIQUE KEY `uq_cob_credito` (`credito_id`),
  KEY `ix_cob_etapa` (`etapa`,`dias_mora`),
  KEY `ix_cob_usuario` (`usuario_id`),
  KEY `fk_cob_gestor` (`gestor_id`),
  CONSTRAINT `fk_cob_credito` FOREIGN KEY (`credito_id`) REFERENCES `creditos` (`id`),
  CONSTRAINT `fk_cob_gestor` FOREIGN KEY (`gestor_id`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_cob_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
