INSERT INTO `comercios` VALUES (1,'ALM-MIRASOL','Almacenes Mirasol','Tienda por departamentos','departamental','Ropa, calzado, perfumería, hogar y juguetes. El almacén de toda la familia, con doce meses sin intereses en compras desde $100.','AM','#6418c3',12,0,1,10,'2026-11-09 14:58:21'),(2,'CASA-LEMPA','Casa Lempa Electrodomésticos','Línea blanca y electrónica','electronica','Refrigeradoras, cocinas, lavadoras, televisores y aire acondicionado, con instalación incluida en el área metropolitana.','CL','#b42318',18,2500,1,20,'2026-11-09 14:58:21'),(3,'SUPER-IZALCO','Super Izalco','Supermercado','supermercado','La despensa completa: abarrotes, carnes, frutas y verduras, limpieza y cuidado personal. Entrega el mismo día.','SI','#0f7a49',0,350,1,30,'2026-11-09 14:58:21'),(4,'TEC-CUSCATLAN','TecnoCuscatlán','Computación y celulares','tecnologia','Teléfonos, computadoras, tabletas, consolas y accesorios, con garantía local de un año.','TC','#1570ef',15,0,1,40,'2026-11-09 14:58:21'),(5,'FARM-SAN-JORGE','Farmacias San Jorge','Farmacia','farmacia','Medicamentos de marca y genéricos, cuidado del bebé, vitaminas y equipo médico básico.','SJ','#039855',0,200,1,50,'2026-11-09 14:58:21'),(6,'MUEBLES-CONCHAGUA','Muebles Conchagua','Mueblería','hogar','Salas, comedores, dormitorios y colchones fabricados en el país, con entrega y armado.','MC','#b54708',24,3500,1,60,'2026-11-09 14:58:21'),(7,'DEPOR-ILOPANGO','Deportes Ilopango','Artículos deportivos','deportes','Calzado y ropa deportiva, bicicletas, equipo de gimnasio y suplementos.','DI','#7a5af8',10,500,1,70,'2026-11-09 14:58:21'),(8,'LIB-CUZCATLAN','Librería Cuzcatlán','Librería y papelería','libreria','Útiles escolares, libros de texto, papelería de oficina y manualidades.','LC','#dd2590',0,250,1,80,'2026-11-09 14:58:21');
