DROP TABLE IF EXISTS `cuentas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cuentas` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `numero_cuenta` varchar(20) NOT NULL,
  `usuario_id` int(10) unsigned NOT NULL,
  `producto_id` smallint(5) unsigned NOT NULL,
  `moneda` char(3) NOT NULL DEFAULT 'USD',
  `saldo_cent` bigint(20) NOT NULL DEFAULT 0,
  `saldo_retenido_cent` bigint(20) NOT NULL DEFAULT 0 COMMENT 'Fondos comprometidos a├║n no liquidados',
  `estado` enum('activa','bloqueada','cerrada','congelada') NOT NULL DEFAULT 'activa',
  `origen` enum('ventanilla','en_linea','migracion') NOT NULL DEFAULT 'ventanilla' COMMENT 'Por donde se abrio la cuenta',
  `compensacion_autorizada` tinyint(1) NOT NULL DEFAULT 1,
  `compensacion_bp` smallint(5) unsigned NOT NULL DEFAULT 10000,
  `compensacion_minimo_cent` int(10) unsigned NOT NULL DEFAULT 0,
  `es_tecnica` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Cuenta interna del banco, no de cliente',
  `apertura_en` datetime NOT NULL DEFAULT current_timestamp(),
  `cerrada_en` datetime DEFAULT NULL COMMENT 'Cuando se cerro la cuenta',
  `cierre_motivo` varchar(200) DEFAULT NULL COMMENT 'Por que se cerro',
  `aviso_inactividad_en` datetime DEFAULT NULL COMMENT 'Cuando se le avisa al titular del cierre proximo',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uuid` (`uuid`),
  UNIQUE KEY `numero_cuenta` (`numero_cuenta`),
  KEY `fk_cuenta_producto` (`producto_id`),
  KEY `idx_usuario` (`usuario_id`),
  KEY `idx_estado` (`estado`),
  KEY `idx_cuentas_inactivas` (`estado`,`saldo_cent`),
  CONSTRAINT `fk_cuenta_producto` FOREIGN KEY (`producto_id`) REFERENCES `productos` (`id`),
  CONSTRAINT `fk_cuenta_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `chk_retenido_no_negativo` CHECK (`saldo_retenido_cent` >= 0),
  CONSTRAINT `chk_saldo_cliente_no_negativo` CHECK (`es_tecnica` = 1 or `saldo_cent` >= 0)
) ENGINE=InnoDB AUTO_INCREMENT=786 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
