--
-- Table structure for table `cuotas`
--

DROP TABLE IF EXISTS `cuotas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cuotas` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `credito_id` int(10) unsigned NOT NULL,
  `numero` smallint(5) unsigned NOT NULL,
  `capital_cent` bigint(20) NOT NULL,
  `interes_cent` bigint(20) NOT NULL,
  `seguro_vida_cent` bigint(20) unsigned NOT NULL DEFAULT 0 COMMENT 'Seguro de vida sobre saldo deudor',
  `seguro_empleo_cent` bigint(20) unsigned NOT NULL DEFAULT 0 COMMENT 'Seguro de desempleo',
  `mora_cent` bigint(20) NOT NULL DEFAULT 0,
  `total_cent` bigint(20) NOT NULL,
  `saldo_posterior_cent` bigint(20) NOT NULL DEFAULT 0,
  `pagado_cent` bigint(20) NOT NULL DEFAULT 0,
  `fecha_vencimiento` date NOT NULL,
  `pagada_en` datetime DEFAULT NULL,
  `asiento_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Asiento con el que se pagó: de ahí sale el comprobante',
  `estado` enum('pendiente','parcial','pagada','vencida','condonada') NOT NULL DEFAULT 'pendiente',
  `dias_mora` smallint(6) NOT NULL DEFAULT 0,
  `pagada_tarde` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_credito_numero` (`credito_id`,`numero`),
  KEY `idx_vencimiento_estado` (`fecha_vencimiento`,`estado`),
  KEY `idx_cuotas_asiento` (`asiento_id`),
  CONSTRAINT `fk_cuota_credito` FOREIGN KEY (`credito_id`) REFERENCES `creditos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3265 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

