--
-- Table structure for table `depositos_plazo`
--

DROP TABLE IF EXISTS `depositos_plazo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `depositos_plazo` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `folio` varchar(24) NOT NULL,
  `usuario_id` int(10) unsigned NOT NULL,
  `cuenta_id` int(10) unsigned NOT NULL,
  `cuenta_origen_id` int(10) unsigned NOT NULL,
  `cuenta_abono_id` int(10) unsigned NOT NULL COMMENT 'Donde se abonan intereses y capital al vencer',
  `monto_cent` bigint(20) NOT NULL,
  `tasa_bp` int(10) unsigned NOT NULL,
  `plazo_dias` smallint(5) unsigned NOT NULL,
  `fecha_inicio` date NOT NULL,
  `fecha_vence` date NOT NULL,
  `renovacion` enum('no','capital','capital_intereses') NOT NULL DEFAULT 'no',
  `renovado_de` bigint(20) unsigned DEFAULT NULL COMMENT 'El depósito del que viene, si se renovó',
  `veces_renovado` smallint(5) unsigned NOT NULL DEFAULT 0,
  `estado` enum('vigente','vencido','liquidado','cancelado','renovado') NOT NULL DEFAULT 'vigente',
  `intereses_cent` bigint(20) NOT NULL DEFAULT 0,
  `retencion_cent` bigint(20) NOT NULL DEFAULT 0,
  `penalidad_cent` bigint(20) NOT NULL DEFAULT 0,
  `asiento_apertura_id` bigint(20) unsigned DEFAULT NULL,
  `asiento_liquidacion_id` bigint(20) unsigned DEFAULT NULL,
  `creado_en` datetime NOT NULL DEFAULT current_timestamp(),
  `liquidado_en` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uuid` (`uuid`),
  UNIQUE KEY `folio` (`folio`),
  UNIQUE KEY `cuenta_id` (`cuenta_id`),
  KEY `fk_dpf_origen` (`cuenta_origen_id`),
  KEY `fk_dpf_abono` (`cuenta_abono_id`),
  KEY `fk_dpf_padre` (`renovado_de`),
  KEY `fk_dpf_as_ap` (`asiento_apertura_id`),
  KEY `fk_dpf_as_liq` (`asiento_liquidacion_id`),
  KEY `idx_usuario` (`usuario_id`,`estado`),
  KEY `idx_vence` (`estado`,`fecha_vence`),
  CONSTRAINT `fk_dpf_abono` FOREIGN KEY (`cuenta_abono_id`) REFERENCES `cuentas` (`id`),
  CONSTRAINT `fk_dpf_as_ap` FOREIGN KEY (`asiento_apertura_id`) REFERENCES `asientos` (`id`),
  CONSTRAINT `fk_dpf_as_liq` FOREIGN KEY (`asiento_liquidacion_id`) REFERENCES `asientos` (`id`),
  CONSTRAINT `fk_dpf_cuenta` FOREIGN KEY (`cuenta_id`) REFERENCES `cuentas` (`id`),
  CONSTRAINT `fk_dpf_origen` FOREIGN KEY (`cuenta_origen_id`) REFERENCES `cuentas` (`id`),
  CONSTRAINT `fk_dpf_padre` FOREIGN KEY (`renovado_de`) REFERENCES `depositos_plazo` (`id`),
  CONSTRAINT `fk_dpf_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `chk_dpf_monto` CHECK (`monto_cent` > 0),
  CONSTRAINT `chk_dpf_fechas` CHECK (`fecha_vence` > `fecha_inicio`)
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

