/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `detalle_usuarios` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `usuario_id` int(10) unsigned NOT NULL,
  `dui` varchar(12) DEFAULT NULL,
  `nit` varchar(20) DEFAULT NULL,
  `telefono` varchar(20) DEFAULT NULL,
  `celular` varchar(20) DEFAULT NULL,
  `telefono_trabajo` varchar(20) DEFAULT NULL,
  `direccion` varchar(255) NOT NULL DEFAULT '',
  `empresa` varchar(255) NOT NULL DEFAULT '',
  `cargo` varchar(255) NOT NULL DEFAULT '',
  `direccion_trabajo` varchar(255) NOT NULL DEFAULT '',
  `ingreso_mensual_cent` bigint(20) NOT NULL DEFAULT 0,
  `fuente_ingreso` enum('empleo','negocio_propio','honorarios','remesas','pension','rentas','otro') DEFAULT NULL COMMENT 'De donde viene el ingreso declarado',
  `ocupacion` varchar(120) DEFAULT NULL COMMENT 'A que se dedica, en sus palabras',
  `antiguedad_meses` smallint(5) unsigned DEFAULT NULL COMMENT 'Cuanto lleva en esa actividad',
  `perfil_declarado_en` datetime DEFAULT NULL COMMENT 'Cuando el cliente declaro sus datos en linea. Despues, solo en agencia',
  `fecha_nacimiento` date DEFAULT NULL,
  `genero` char(1) DEFAULT NULL,
  `estado_civil` varchar(30) DEFAULT NULL,
  `foto_dui_frontal` varchar(255) DEFAULT NULL,
  `foto_dui_reverso` varchar(255) DEFAULT NULL,
  `foto_nit` varchar(255) DEFAULT NULL,
  `foto_firma` varchar(255) DEFAULT NULL,
  `perfil_completo` tinyint(1) NOT NULL DEFAULT 0,
  `actualizado_en` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `usuario_id` (`usuario_id`),
  KEY `idx_dui` (`dui`),
  CONSTRAINT `fk_det_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=199 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

