DROP TABLE IF EXISTS `movimientos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `movimientos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `asiento_id` bigint(20) unsigned NOT NULL,
  `cuenta_id` int(10) unsigned NOT NULL,
  `importe_cent` bigint(20) NOT NULL,
  `moneda` char(3) NOT NULL DEFAULT 'USD',
  `saldo_posterior_cent` bigint(20) NOT NULL,
  `descripcion` varchar(255) NOT NULL DEFAULT '',
  `creado_en` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  PRIMARY KEY (`id`),
  KEY `idx_cuenta_fecha` (`cuenta_id`,`creado_en`),
  KEY `idx_asiento` (`asiento_id`),
  CONSTRAINT `fk_mov_asiento` FOREIGN KEY (`asiento_id`) REFERENCES `asientos` (`id`),
  CONSTRAINT `fk_mov_cuenta` FOREIGN KEY (`cuenta_id`) REFERENCES `cuentas` (`id`),
  CONSTRAINT `chk_importe_no_cero` CHECK (`importe_cent` <> 0)
) ENGINE=InnoDB AUTO_INCREMENT=5437 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
