DROP TABLE IF EXISTS `ordenes_programadas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ordenes_programadas` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `folio` varchar(24) NOT NULL,
  `usuario_id` int(10) unsigned NOT NULL,
  `alias` varchar(60) NOT NULL DEFAULT '' COMMENT 'Como la llama el cliente: "Alquiler", "Tarjeta"',
  `tipo` enum('transferencia','interbancaria','servicio','tarjeta','credito') NOT NULL,
  `cuenta_origen_id` int(10) unsigned NOT NULL,
  `cuenta_destino_id` int(10) unsigned DEFAULT NULL,
  `beneficiario_id` int(10) unsigned DEFAULT NULL,
  `convenio_id` smallint(5) unsigned DEFAULT NULL,
  `referencia` varchar(48) NOT NULL DEFAULT '',
  `tarjeta_id` int(10) unsigned DEFAULT NULL,
  `credito_id` int(10) unsigned DEFAULT NULL,
  `modo_monto` enum('fijo','total','minimo') NOT NULL DEFAULT 'fijo',
  `monto_cent` bigint(20) NOT NULL DEFAULT 0,
  `tope_cent` bigint(20) NOT NULL DEFAULT 0,
  `concepto` varchar(160) NOT NULL DEFAULT '',
  `frecuencia` enum('unica','semanal','quincenal','mensual','bimestral','trimestral','semestral','anual') NOT NULL DEFAULT 'mensual',
  `dia_mes` tinyint(3) unsigned DEFAULT NULL COMMENT 'Día del mes, 1-31. Si el mes no lo tiene, se usa el último.',
  `dia_semana` tinyint(3) unsigned DEFAULT NULL COMMENT '1 lunes … 7 domingo',
  `fecha_inicio` date NOT NULL,
  `fecha_fin` date DEFAULT NULL COMMENT 'Sin fecha, hasta que la cancelen',
  `proxima_en` date NOT NULL,
  `estado` enum('activa','pausada','terminada','cancelada') NOT NULL DEFAULT 'activa',
  `reintentos_max` tinyint(3) unsigned NOT NULL DEFAULT 3,
  `reintentos_hechos` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `fallos_consecutivos` smallint(5) unsigned NOT NULL DEFAULT 0,
  `ejecuciones` int(10) unsigned NOT NULL DEFAULT 0,
  `ultima_en` datetime DEFAULT NULL,
  `creado_en` datetime NOT NULL DEFAULT current_timestamp(),
  `cancelada_en` datetime DEFAULT NULL,
  `motivo_fin` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uuid` (`uuid`),
  UNIQUE KEY `folio` (`folio`),
  KEY `fk_ord_origen` (`cuenta_origen_id`),
  KEY `fk_ord_destino` (`cuenta_destino_id`),
  KEY `fk_ord_benef` (`beneficiario_id`),
  KEY `fk_ord_convenio` (`convenio_id`),
  KEY `fk_ord_tarjeta` (`tarjeta_id`),
  KEY `fk_ord_credito` (`credito_id`),
  KEY `idx_pendientes` (`estado`,`proxima_en`),
  KEY `idx_usuario` (`usuario_id`,`estado`),
  CONSTRAINT `fk_ord_benef` FOREIGN KEY (`beneficiario_id`) REFERENCES `beneficiarios` (`id`),
  CONSTRAINT `fk_ord_convenio` FOREIGN KEY (`convenio_id`) REFERENCES `convenios_servicio` (`id`),
  CONSTRAINT `fk_ord_credito` FOREIGN KEY (`credito_id`) REFERENCES `creditos` (`id`),
  CONSTRAINT `fk_ord_destino` FOREIGN KEY (`cuenta_destino_id`) REFERENCES `cuentas` (`id`),
  CONSTRAINT `fk_ord_origen` FOREIGN KEY (`cuenta_origen_id`) REFERENCES `cuentas` (`id`),
  CONSTRAINT `fk_ord_tarjeta` FOREIGN KEY (`tarjeta_id`) REFERENCES `tarjetas` (`id`),
  CONSTRAINT `fk_ord_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `chk_ord_monto` CHECK (`modo_monto` <> 'fijo' or `monto_cent` > 0)
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
