--
-- Table structure for table `pagos_servicio`
--

DROP TABLE IF EXISTS `pagos_servicio`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pagos_servicio` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `folio` varchar(24) NOT NULL,
  `usuario_id` int(10) unsigned NOT NULL,
  `cuenta_id` int(10) unsigned NOT NULL,
  `convenio_id` smallint(5) unsigned NOT NULL,
  `guardado_id` int(10) unsigned DEFAULT NULL,
  `referencia` varchar(48) NOT NULL,
  `titular` varchar(140) NOT NULL DEFAULT '',
  `monto_cent` bigint(20) NOT NULL,
  `deuda_cent` bigint(20) NOT NULL DEFAULT 0,
  `comision_cent` bigint(20) NOT NULL DEFAULT 0,
  `periodo` varchar(40) NOT NULL DEFAULT '' COMMENT 'El periodo facturado, tal como lo da el colector',
  `vence_el` date DEFAULT NULL,
  `estado` enum('aplicado','liquidado','reversado') NOT NULL DEFAULT 'aplicado',
  `motivo` varchar(160) NOT NULL DEFAULT '',
  `autorizacion` varchar(40) NOT NULL DEFAULT '',
  `asiento_id` bigint(20) unsigned DEFAULT NULL,
  `asiento_reverso_id` bigint(20) unsigned DEFAULT NULL,
  `creado_en` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `liquidado_en` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uuid` (`uuid`),
  UNIQUE KEY `folio` (`folio`),
  KEY `fk_pagoserv_cuenta` (`cuenta_id`),
  KEY `fk_pagoserv_guardado` (`guardado_id`),
  KEY `fk_pagoserv_asiento` (`asiento_id`),
  KEY `fk_pagoserv_reverso` (`asiento_reverso_id`),
  KEY `idx_usuario_fecha` (`usuario_id`,`creado_en`),
  KEY `idx_estado` (`estado`,`creado_en`),
  KEY `idx_convenio` (`convenio_id`,`creado_en`),
  CONSTRAINT `fk_pagoserv_asiento` FOREIGN KEY (`asiento_id`) REFERENCES `asientos` (`id`),
  CONSTRAINT `fk_pagoserv_convenio` FOREIGN KEY (`convenio_id`) REFERENCES `convenios_servicio` (`id`),
  CONSTRAINT `fk_pagoserv_cuenta` FOREIGN KEY (`cuenta_id`) REFERENCES `cuentas` (`id`),
  CONSTRAINT `fk_pagoserv_guardado` FOREIGN KEY (`guardado_id`) REFERENCES `servicios_guardados` (`id`),
  CONSTRAINT `fk_pagoserv_reverso` FOREIGN KEY (`asiento_reverso_id`) REFERENCES `asientos` (`id`),
  CONSTRAINT `fk_pagoserv_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `chk_pagoserv_monto` CHECK (`monto_cent` > 0)
) ENGINE=InnoDB AUTO_INCREMENT=67 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

