  `tasa_min_bp` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Tasa anual mínima en puntos base',
  `tasa_max_bp` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Tasa anual máxima en puntos base',
  `saldo_minimo_cent` bigint(20) NOT NULL DEFAULT 0,
