  `linea_desde_cent` bigint(20) unsigned NOT NULL DEFAULT 0 COMMENT 'Línea de crédito inicial de referencia',
  `monto_minimo_cent` bigint(20) unsigned NOT NULL DEFAULT 0 COMMENT 'Monto mínimo que se concede en este producto',
  `monto_maximo_cent` bigint(20) unsigned NOT NULL DEFAULT 0 COMMENT 'Techo del producto. 0 = sin tope propio',
  `plazo_minimo` smallint(5) unsigned NOT NULL DEFAULT 6,
  `plazo_maximo` smallint(5) unsigned NOT NULL DEFAULT 60,
  `plazo_financiamiento_meses` smallint(5) unsigned DEFAULT NULL COMMENT 'Tarjetas: meses máximos para amortizar el saldo revolvente',
  `membresia_anual_cent` bigint(20) unsigned NOT NULL DEFAULT 0 COMMENT 'Membresía anual; 0 = sin membresía',
