  `marca_emision` varchar(20) DEFAULT NULL COMMENT 'Marca en la que se emite esta línea: visa, mastercard o amex',
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  `publico` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Se muestra en el sitio público',
