DROP TABLE IF EXISTS `solicitud_tarjeta_historial`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `solicitud_tarjeta_historial` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `solicitud_id` int(10) unsigned NOT NULL,
  `etapa_anterior` enum('capturada','revision_atencion','revision_gerencia','aprobada','rechazada','emitida') DEFAULT NULL COMMENT 'NULL en el primer paso: antes no había nada',
  `etapa_nueva` enum('capturada','revision_atencion','revision_gerencia','aprobada','rechazada','emitida') NOT NULL,
  `actor_id` int(10) unsigned DEFAULT NULL,
  `nota` varchar(300) DEFAULT NULL,
  `creado_en` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_hist_actor` (`actor_id`),
  KEY `ix_hist_solicitud` (`solicitud_id`,`id`),
  CONSTRAINT `fk_hist_actor` FOREIGN KEY (`actor_id`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_hist_solicitud` FOREIGN KEY (`solicitud_id`) REFERENCES `solicitudes_tarjeta` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
