--
-- Table structure for table `solicitudes_credito`
--

DROP TABLE IF EXISTS `solicitudes_credito`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `solicitudes_credito` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `folio` varchar(24) NOT NULL,
  `usuario_id` int(10) unsigned NOT NULL,
  `producto_id` smallint(5) unsigned NOT NULL,
  `monto_cent` bigint(20) NOT NULL,
  `plazo_meses` smallint(5) unsigned NOT NULL,
  `tasa_bp` int(10) unsigned DEFAULT NULL COMMENT 'Tasa anual pactada en puntos base; NULL = la del producto',
  `destino` varchar(255) NOT NULL DEFAULT '',
  `ingreso_cent` bigint(20) NOT NULL DEFAULT 0,
  `buro_consulta_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Consulta de buró que respaldó la evaluación',
  `evaluacion_id` bigint(20) unsigned DEFAULT NULL COMMENT 'La evaluación de riesgo con la que se resolvió',
  `capacidad_maxima_cent` bigint(20) unsigned DEFAULT NULL COMMENT 'Monto máximo que admitía la capacidad de pago al capturar',
  `etapa` enum('capturada','revision_atencion','revision_gerencia','revision_presidencia','aprobada','rechazada','desembolsada') NOT NULL DEFAULT 'capturada',
  `revisado_atencion_por` int(10) unsigned DEFAULT NULL,
  `revisado_gerencia_por` int(10) unsigned DEFAULT NULL,
  `revisado_presidencia_por` int(10) unsigned DEFAULT NULL,
