--
-- Table structure for table `tarjetas`
--

DROP TABLE IF EXISTS `tarjetas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tarjetas` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `usuario_id` int(10) unsigned NOT NULL,
  `cuenta_id` int(10) unsigned DEFAULT NULL COMMENT 'Cuenta de d├®bito asociada',
  `producto_id` smallint(5) unsigned DEFAULT NULL COMMENT 'Producto del catálogo al que pertenece la tarjeta',
  `token` char(40) NOT NULL,
  `pan_cifrado` varbinary(512) NOT NULL,
  `pan_hash` char(64) NOT NULL,
  `ultimos4` char(4) NOT NULL,
  `bin6` char(6) NOT NULL,
  `marca` enum('visa','mastercard','amex','discover','desconocida') NOT NULL,
  `tipo` enum('debito','credito','prepago') NOT NULL,
  `titular` varchar(120) NOT NULL,
  `alias` varchar(40) DEFAULT NULL,
  `expira_mes` tinyint(3) unsigned NOT NULL,
  `expira_anio` smallint(5) unsigned NOT NULL,
  `limite_cent` bigint(20) NOT NULL DEFAULT 0,
  `limite_diario_cent` bigint(20) NOT NULL DEFAULT 100000,
  `sobregiro_permitido` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Si se admite consumir por encima del cupo',
  `sobregiro_tolerancia_bp` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Cuanto se admite pasarse, en puntos base del limite (1000 = 10%)',
  `pago_automatico` enum('no','minimo','total') NOT NULL DEFAULT 'no' COMMENT 'Domiciliacion del pago al vencimiento',
  `pago_automatico_cuenta_id` int(10) unsigned DEFAULT NULL COMMENT 'Cuenta de la que se debita el pago automatico',
  `alerta_consumo_cent` bigint(20) NOT NULL DEFAULT 0 COMMENT 'Avisar al titular cuando una compra supere este monto (0 = no avisar)',
  `saldo_usado_cent` bigint(20) NOT NULL DEFAULT 0,
  `dia_corte` tinyint(3) unsigned NOT NULL DEFAULT 25,
  `dias_para_pago` tinyint(3) unsigned NOT NULL DEFAULT 20,
  `estado` enum('activa','bloqueada','vencida','cancelada','pendiente_activacion','inhabilitada') NOT NULL DEFAULT 'pendiente_activacion',
  `pin_hash` varchar(255) DEFAULT NULL COMMENT 'Argon2id, nunca el PIN',
  `pasarela` varchar(30) DEFAULT NULL,
  `pasarela_token` varchar(190) DEFAULT NULL,
  `emitida_en` datetime NOT NULL DEFAULT current_timestamp(),
  `activada_en` datetime DEFAULT NULL,
  `bienvenida_vista_en` datetime DEFAULT NULL COMMENT 'Cuando se le dio la bienvenida al titular. NULL = pendiente',
  `cancelada_en` datetime DEFAULT NULL,
  `compras_internet` tinyint(1) NOT NULL DEFAULT 1,
  `compras_exterior` tinyint(1) NOT NULL DEFAULT 0,
  `contactless` tinyint(1) NOT NULL DEFAULT 1,
  `congelada_hasta` datetime DEFAULT NULL COMMENT 'Bloqueo temporal por el titular',
  `tasa_diferido_bp` int(10) unsigned NOT NULL DEFAULT 1800,
  `ultimo_corte` date DEFAULT NULL,
  `proximo_corte` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uuid` (`uuid`),
  UNIQUE KEY `token` (`token`),
  UNIQUE KEY `pan_hash` (`pan_hash`),
  KEY `fk_tarjeta_cuenta` (`cuenta_id`),
  KEY `idx_usuario` (`usuario_id`),
  KEY `idx_estado` (`estado`),
  KEY `fk_tarjeta_producto` (`producto_id`),
  KEY `fk_tarjetas_pago_auto_cuenta` (`pago_automatico_cuenta_id`),
  KEY `ix_tarjeta_cuenta` (`cuenta_id`),
  KEY `ix_tarjetas_bienvenida` (`usuario_id`,`bienvenida_vista_en`),
  CONSTRAINT `fk_tarjeta_cuenta` FOREIGN KEY (`cuenta_id`) REFERENCES `cuentas` (`id`),
  CONSTRAINT `fk_tarjeta_producto` FOREIGN KEY (`producto_id`) REFERENCES `productos` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_tarjeta_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_tarjetas_pago_auto_cuenta` FOREIGN KEY (`pago_automatico_cuenta_id`) REFERENCES `cuentas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_limite_no_negativo` CHECK (`limite_cent` >= 0),
  CONSTRAINT `chk_usado_no_negativo` CHECK (`saldo_usado_cent` >= 0),
  CONSTRAINT `chk_mes_valido` CHECK (`expira_mes` between 1 and 12)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

