CREATE TABLE `tienda_pedidos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `folio` varchar(24) NOT NULL,
  `usuario_id` int(10) unsigned DEFAULT NULL COMMENT 'Nulo cuando compra un invitado sin cuenta',
  `comercio_id` smallint(5) unsigned NOT NULL,
  `tarjeta_id` int(10) unsigned DEFAULT NULL,
  `medio_pago` enum('tarjeta_emitida','pasarela') NOT NULL DEFAULT 'tarjeta_emitida' COMMENT 'Con que se cobro: una tarjeta de la casa o la pasarela',
  `subtotal_cent` bigint(20) unsigned NOT NULL DEFAULT 0,
  `envio_cent` bigint(20) unsigned NOT NULL DEFAULT 0,
  `total_cent` bigint(20) unsigned NOT NULL DEFAULT 0,
  `cuotas` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `movimiento_id` bigint(20) unsigned DEFAULT NULL,
  `pago_pasarela_id` bigint(20) unsigned DEFAULT NULL COMMENT 'El cobro en la pasarela que respalda este pedido',
  `referencia` varchar(40) NOT NULL,
  `grupo_pago` char(16) DEFAULT NULL COMMENT 'Pedidos cobrados juntos en un solo pago de pasarela',
  `estado` enum('pago_pendiente','pagado','preparando','enviado','entregado','anulado') NOT NULL DEFAULT 'pago_pendiente',
  `cerrado_motivo` varchar(240) DEFAULT NULL COMMENT 'Por qué se anuló: rechazo, caducidad o decisión interna',
  `cerrado_en` datetime DEFAULT NULL,
  `direccion` varchar(400) DEFAULT NULL,
  `transportista` varchar(120) DEFAULT NULL COMMENT 'Quien lleva el pedido',
  `guia` varchar(60) DEFAULT NULL COMMENT 'Numero de guia para rastrear con el transportista',
  `entrega_estimada` date DEFAULT NULL COMMENT 'Fecha que la tienda promete',
  `nota_despacho` varchar(300) DEFAULT NULL COMMENT 'Lo que la tienda quiera decirle al cliente',
  `preparando_en` datetime DEFAULT NULL,
  `enviado_en` datetime DEFAULT NULL,
  `entregado_en` datetime DEFAULT NULL,
  `invitado_nombre` varchar(140) DEFAULT NULL,
  `invitado_correo` varchar(190) DEFAULT NULL,
  `invitado_telefono` varchar(30) DEFAULT NULL,
  `invitado_documento` varchar(20) DEFAULT NULL,
  `invitado_tipo_documento` enum('dui','nit','residente') DEFAULT NULL,
  `clave_consulta` char(12) DEFAULT NULL,
  `creado_en` datetime NOT NULL DEFAULT current_timestamp(),
  `actualizado_en` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pedidos_uuid` (`uuid`),
  UNIQUE KEY `uq_pedidos_folio` (`folio`),
  UNIQUE KEY `uq_pedidos_referencia` (`referencia`),
  KEY `ix_pedidos_usuario` (`usuario_id`,`id`),
  KEY `fk_pedidos_comercio` (`comercio_id`),
  KEY `fk_pedidos_tarjeta` (`tarjeta_id`),
  KEY `ix_pedidos_invitado` (`invitado_correo`),
  KEY `fk_pedidos_pasarela` (`pago_pasarela_id`),
  KEY `idx_pedidos_grupo` (`grupo_pago`),
  KEY `idx_pedidos_estado_comercio` (`comercio_id`,`estado`),
  CONSTRAINT `fk_pedidos_comercio` FOREIGN KEY (`comercio_id`) REFERENCES `comercios` (`id`),
  CONSTRAINT `fk_pedidos_pasarela` FOREIGN KEY (`pago_pasarela_id`) REFERENCES `pagos_pasarela` (`id`),
  CONSTRAINT `fk_pedidos_tarjeta` FOREIGN KEY (`tarjeta_id`) REFERENCES `tarjetas` (`id`),
  CONSTRAINT `fk_pedidos_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
